// Generated by tools/extract-hook.js from Frontend/src/modules/Food/pages/restaurant/EditCuisines.jsx (EditCuisines), then edited by hand
// where the web code touched the DOM. The logic is the web page's own.
/* eslint-disable react-hooks/exhaustive-deps, no-unused-vars, no-empty */
import { useState, useEffect } from 'react'
import { useNavigate } from '../../../lib/webRouter'
import { restaurantAPI } from '../../../api/restaurant'
import { localStore } from '../../../lib/storage'
import { events } from '../../../lib/events'

const CUISINES_STORAGE_KEY = "restaurant_cuisines"

const ALL_CUISINES = [
  "Burger",
  "Chinese",
  "Momos",
  "North Indian",
  "Pizza",
  "Rolls",
  "Sandwich",
  "Shawarma",
  "South Indian",
  "Biryani",
  "Desserts",
  "Ice Cream",
  "Fast Food",
  "Cafe",
  "Italian",
  "Mexican",
  "Thai",
  "Seafood",
  "Salad",
  "Healthy Food",
  "Juices",
  "Beverages",
  "Punjabi",
  "Gujarati",
  "Rajasthani",
  "Mughlai",
  "Street Food",
  "Bakery",
]

const DEFAULT_SELECTED = [
  "Burger",
  "Chinese",
  "Momos",
  "North Indian",
  "Pizza",
  "Rolls",
  "Sandwich",
  "Shawarma",
]

export function useEditCuisines() {
  const navigate = useNavigate()
  const [search, setSearch] = useState("")
  const [selected, setSelected] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState("")

  // Fetch current cuisines from backend
  useEffect(() => {
    const fetchCuisines = async () => {
      try {
        setLoading(true)
        const response = await restaurantAPI.getCurrentRestaurant()
        const data = response?.data?.data?.restaurant || response?.data?.restaurant
        if (data?.cuisines && Array.isArray(data.cuisines) && data.cuisines.length > 0) {
          setSelected(data.cuisines)
        } else {
          // Fallback to localStore
          try {
            const saved = localStore.getItem(CUISINES_STORAGE_KEY)
            if (saved) {
              const parsed = JSON.parse(saved)
              if (Array.isArray(parsed) && parsed.length) {
                setSelected(parsed)
              } else {
                setSelected(DEFAULT_SELECTED)
              }
            } else {
              setSelected(DEFAULT_SELECTED)
            }
          } catch (e) {
            console.error("Error loading cuisines from localStore:", e)
            setSelected(DEFAULT_SELECTED)
          }
        }
      } catch (error) {
        console.error("Error fetching cuisines:", error)
        // Fallback to localStore
        try {
          const saved = localStore.getItem(CUISINES_STORAGE_KEY)
          if (saved) {
            const parsed = JSON.parse(saved)
            if (Array.isArray(parsed) && parsed.length) {
              setSelected(parsed)
            } else {
              setSelected(DEFAULT_SELECTED)
            }
          } else {
            setSelected(DEFAULT_SELECTED)
          }
        } catch (e) {
          console.error("Error loading cuisines from localStore:", e)
          setSelected(DEFAULT_SELECTED)
        }
      } finally {
        setLoading(false)
      }
    }

    fetchCuisines()
  }, [])

  // Lenis smooth scrolling

  const handleToggle = (name) => {
    const isSelected = selected.includes(name)
    if (!isSelected && selected.length >= 8) {
      setError("You cannot select more than 8 cuisines")
      // Hide after a short delay
      setTimeout(() => setError(""), 2500)
      return
    }
    setSelected((prev) =>
      isSelected ? prev.filter((c) => c !== name) : [...prev, name]
    )
  }

  const handleUpdate = async () => {
    try {
      // Save to backend API
      const response = await restaurantAPI.updateProfile({ cuisines: selected })
      
      if (response?.data?.data?.restaurant) {
        // Also save to localStore as backup
        try {
          localStore.setItem(CUISINES_STORAGE_KEY, JSON.stringify(selected))
          events.emit("cuisinesUpdated")
        } catch (e) {
          console.error("Error saving cuisines to localStore:", e)
        }
        navigate(-1)
      } else {
        throw new Error("Invalid response from server")
      }
    } catch (error) {
      console.error("Error updating cuisines:", error)
    }
  }

  const filtered = ALL_CUISINES.filter((name) =>
    name.toLowerCase().includes(search.toLowerCase())
  )

  const recommendedSet = new Set(DEFAULT_SELECTED)

  return {
    navigate,
    search,
    setSearch,
    selected,
    setSelected,
    loading,
    setLoading,
    error,
    setError,
    handleToggle,
    handleUpdate,
    filtered,
    recommendedSet,
    CUISINES_STORAGE_KEY,
    ALL_CUISINES,
    DEFAULT_SELECTED,
  }
}
